const int utf8_length = ::WideCharToMultiByte(
    CP_UTF8, WC_ERR_INVALID_CHARS, arg, source_length,
    nullptr, 0, nullptr, nullptr);
if (utf8_length <= 0) {
    throw std::runtime_error(kConversionError);
}

std::string converted(static_cast<std::size_t>(utf8_length), '\0');

// Second call: perform the conversion into the exact buffer size.
const int written = ::WideCharToMultiByte(
    CP_UTF8, WC_ERR_INVALID_CHARS, arg, source_length,
    converted.data(), utf8_length, nullptr, nullptr);
if (written != utf8_length) {
    throw std::runtime_error(kConversionError);
}

result.push_back(std::move(converted));

int wmain(int argc, wchar_t** argv) {
    try {
        auto strings = platform::utf8_arguments(argc, argv);
        // Construct the borrowed pointers after the owning strings stop moving.
        std::vector<char*> arguments;
        arguments.reserve(strings.size() + 1);
        for (auto& value : strings) arguments.push_back(value.data());
        arguments.push_back(nullptr);
        return guarded_run(argc, arguments.data());
    } catch (const std::exception&) {
        std::fprintf(stderr, "command line initialization failed\n");
        return 1;
    }
}

def parse_port_line(line: bytes) -> int:
    """Accept only the announced line ending variants, not arbitrary whitespace."""
    match = re.fullmatch(rb"PORT ([1-9][0-9]{0,4})\r?\n", line)
    if match is None:
        raise RuntimeError("service reported an invalid port line")
    port = int(match[1])
    if not 1 <= port <= 65535:
        raise RuntimeError("service port out of range")
    return port
